const crypto = require('crypto');

function sha256(value) {
  return crypto.createHash('sha256').update(String(value || '')).digest('hex');
}

function headerValue(headers, name) {
  if (!name) return undefined;
  return headers[name] || headers[String(name).toLowerCase()];
}

const input = $input.first().json;
const body = input.body || input;
const headers = input.headers || {};
const rawBody = typeof input.rawBody === 'string' ? input.rawBody : JSON.stringify(body);

const signatureHeaderName = $env.ECHAT_SIGNATURE_HEADER;
const secret = $env.ECHAT_WEBHOOK_SECRET;
let assinaturaOk = false;
let assinaturaMotivo = 'assinatura_nao_configurada_placeholder_eas';

if (signatureHeaderName && secret) {
  const received = headerValue(headers, signatureHeaderName);
  if (!received) {
    assinaturaMotivo = 'assinatura_ausente';
  } else {
    const expected = crypto.createHmac('sha256', secret).update(rawBody).digest('hex');
    const normalized = String(received).replace(/^sha256=/, '');
    assinaturaOk = normalized.length === expected.length && crypto.timingSafeEqual(Buffer.from(normalized), Buffer.from(expected));
    assinaturaMotivo = assinaturaOk ? 'assinatura_valida' : 'assinatura_invalida';
  }
}

const rawText = String(body.message || body.text || body.content || '');
const eventId = String(body.event_id || body.id || '');
const rejeitado = !assinaturaOk || !eventId;
const now = new Date();
const keyType = rejeitado ? 'event_rejeitado' : 'event';
const keyValue = eventId || `sem-event-id-${$execution.id}`;

const payloadMinimo = {
  event_id: eventId,
  event_type: String(body.event_type || body.type || body.event || 'desconhecido'),
  channel: String(body.channel || body.canal || 'desconhecido'),
  conversation_id: String(body.conversation_id || body.conversation?.id || ''),
  message_id: String(body.message_id || body.message?.id || ''),
  occurred_at: String(body.occurred_at || body.timestamp || now.toISOString()),
  raw_text_sha256: rawText ? sha256(rawText) : null,
  raw_text_length: rawText.length,
  has_attachment: Boolean(body.attachment || body.attachments?.length),
  source_system: 'e-chat',
  modo: 'espelho',
  assinatura: assinaturaMotivo
};

return [{ json: {
  status_pre_banco: rejeitado ? 'rejeitado' : 'validado',
  http_status_pre_banco: !assinaturaOk ? 401 : (!eventId ? 400 : 200),
  motivo_pre_banco: !assinaturaOk ? assinaturaMotivo : (!eventId ? 'event_id_ausente' : 'evento_valido'),
  idempotency_key_type: keyType,
  idempotency_key_value: keyValue,
  expires_at_sql: rejeitado ? "now() + interval '24 hours'" : "now() + interval '24 hours'",
  log_payload: payloadMinimo,
  process_brain: false,
  sends_external_message: false
} }];

const banco = $input.first().json || {};
const pre = $('Validar assinatura e minimizar payload').first().json;
const duplicado = pre.idempotency_key_type === 'event' && banco.inserted !== true;

let status = pre.status_pre_banco;
let httpStatus = pre.http_status_pre_banco;
let motivo = pre.motivo_pre_banco;

if (duplicado) {
  status = 'duplicado';
  httpStatus = 200;
  motivo = 'event_id_duplicado_24h';
}

if (status === 'validado') {
  status = 'registrado_modo_espelho';
  motivo = 'f1_nao_chama_cerebro_nesta_fase';
}

return [{ json: {
  workflow: 'SST · F1 Entrada E-Chat',
  status,
  motivo,
  http_status: httpStatus,
  process_brain: false,
  sends_external_message: false,
  duplicate: duplicado,
  idempotency: {
    key_type: banco.key_type,
    key_value: banco.key_value,
    inserted: banco.inserted === true,
    hit_count: banco.hit_count || 0
  },
  mirror_mode: true
} }];

const pre = $('Validar assinatura e minimizar payload').first().json;
return [{ json: {
  workflow: 'SST · F1 Entrada E-Chat',
  status: 'fila_humana',
  motivo: 'falha_persistencia_idempotencia',
  http_status: 200,
  process_brain: false,
  sends_external_message: false,
  retry_automatico: false,
  alerts: ['alerta_falha_banco_idempotencia'],
  idempotency: {
    key_type: pre.idempotency_key_type,
    key_value: pre.idempotency_key_value,
    inserted: false,
    hit_count: 0
  },
  mirror_mode: true
} }];
